/// <summary>
/// MPJ_2864 - kscerri - 22/03/2021
/// Subtask class created to process all sub task process
/// </summary>
public class METPopulateCustCreditLimitSubTaskService
{
}

Method.Source:
    /// <summary>
    /// MPJ_2864 - kscerri - 22/03/2021
    /// processSubTask contains the business logic to create/update according to the task and its parameters
    /// </summary>
    /// <param name = "_dataContract">Contract contains the custAccount list required per task</param>
    public void processSubTask(METPopulateCustCreditLimitContract _dataContract)
    {
        CustTable                           custTable;
        METCustCreditLimit                  metCustCreditLimit;
        METCustTable                        metCustTable;
        AmountMST                           balance;
        CustAccount                         fromCustomer, toCustomer;
        METPopulateCustCreditLimitService   populateCustCreditLimitService = new METPopulateCustCreditLimitService();
        List                                custAccounts                   = new List(Types::String);
        ListEnumerator                      enumerator;


        custAccounts    = _dataContract.getCustAccountList();
        enumerator      = custAccounts.getEnumerator();

        while (enumerator.moveNext())
        {
            select firstonly CreditMax, AccountNum from custTable
                where custTable.AccountNum == enumerator.current()
                outer join firstonly metCustTable
                    where metCustTable.AccountNum == custTable.AccountNum
                outer join firstonly metCustCreditLimit
                    where metCustCreditLimit.AccountNum == custTable.AccountNum;
            
            balance = populateCustCreditLimitService.getBalance(custTable.AccountNum);

            if (metCustCreditLimit)
            {
                ttsbegin;
                metCustCreditLimit.selectForUpdate(true);
                metCustCreditLimit.FrozenBalance    = metCustTable.FrozenBalance;
                metCustCreditLimit.ArrearsFlag      = metCustTable.ArrearsFlag;
                metCustCreditLimit.Balance          = balance;
                metCustCreditLimit.CreditLimit      = custTable.CreditMax;
                metCustCreditLimit.update();
                ttscommit;
            }
            else
            {
                metCustCreditLimit.AccountNum       = custTable.AccountNum;
                metCustCreditLimit.FrozenBalance    = metCustTable.FrozenBalance;
                metCustCreditLimit.ArrearsFlag      = metCustTable.ArrearsFlag;
                metCustCreditLimit.Balance          = balance;
                metCustCreditLimit.CreditLimit      = custTable.CreditMax;
                metCustCreditLimit.insert();
            }
        }
    }
